.bar { background:#e6eaf2; height:9px; width:100%; }
.bar > div { background:#1f3864; height:9px; }


/* demo watermark - remove for production */
.print-format { position: relative; }
.print-format::before {
  content: "DEMONSTRATION \2014 NOT A STATUTORY DOCUMENT";
  position: fixed;
  top: 42%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-24deg);
  font-size: 34px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(155, 28, 28, 0.13);
  white-space: nowrap;
  pointer-events: none;
  z-index: 0;
}
.print-format > * { position: relative; z-index: 1; }

